import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"滚动升级","description":"","frontmatter":{"title":"滚动升级","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rolling-upgrade.md","filePath":"cs/rolling-upgrade.md","lastUpdated":1789023840000}'),h={name:"cs/rolling-upgrade.md"};function _(E,a,u,m,f,A){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="滚动升级" tabindex="-1">滚动升级 <a class="header-anchor" href="#滚动升级" aria-label="Permalink to &quot;滚动升级&quot;">​</a></h1><div class="epigraph"><p>一次换一副本，集群保持法定人数。窗口里新旧二进制共存，协议必须向前或向后兼容，否则升级本身就是分区。</p><footer>—— 据 Google SRE 实践；Raft/Paxos 成员与版本混合；Kubernetes 滚动更新整理</footer></div><p>上一课<a href="/cs/geo-replication">地理复制</a>让多版本更常见。缺口是<strong>变更怎么上线</strong>：停机切全部违反可用性；滚动切要求混合版本正确。本课钉兼容与法定人数，不重写 k8s 控制器。分布式系统课序下一课用 TLA+ 给协议收口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>滚动：每次下 \\(k\\) 个实例，等健康再继续。对 Raft：活着的旧+新必须仍能凑多数派，且日志格式能互读。对 API：生产者新字段，消费者旧代码忽略（前向）；旧生产者缺字段，新代码有默认（后向）。双向窗口要先扩消费者再扩生产者，或反过来按依赖——顺序是规格。</p><p>缺口：把滚动当「没有故障」。滚动是可控的漏发与崩溃停实验，检测器会抖，对冲会打到旧实例。</p><p><span class="marginnote">SRE 书强调金丝雀与错误预算。协议课强调混合版本的状态机 \\(\\delta\\) 必须对旧条目仍确定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两阶段升级：先发只读懂新旧的代码，再发只写新的代码。Feature flag 把行为与二进制解开。etcd/k8s：先升数据面再升控制面或按文档顺序，避免 API 服务器比 kubelet 更新时的未知字段。</p>',9)),(e(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAN%5B%22%E9%87%91%E4%B8%9D%E9%9B%80%22%5D%20--%3E%20MIX%5B%22%E6%B7%B7%E5%90%88%E7%89%88%E6%9C%AC%22%5D%0A%20%20MIX%20--%3E%20COMP%5B%22%E7%BC%96%E8%A7%A3%E7%A0%81%E5%85%BC%E5%AE%B9%22%5D%0A%20%20MIX%20--%3E%20Q%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%E4%BB%8D%E5%9C%A8%22%5D%0A%20%20COMP%20--%3E%20FULL%5B%22%E5%85%A8%E9%87%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>不要在滚动中途改多数派定义（成员变更课）除非协议允许嵌套。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>脑裂：新旧若用不同选举超时默认值，可能一边更易当选。配置默认值也是协议。Schema：protobuf 字段号稳定性比 JSON 随意增删更可滚动。</p><p>本课不写蓝绿与金丝雀的产品对照全书。也不写应用迁移 SQL 的全部坑，只点名：存储 schema 滚动与二进制滚动要同一纪律。</p><p>失败回滚：必须能反向兼容，否则只能前进。这是单向飞行——要在设计里避免。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把每次发布当混沌实验替代。后课默认：协议变更走两阶段兼容；滚动窗口里 SLO 用尾延迟盯着。TLA+ 下一课可把「新旧消息交错」写成状态，比在生产第一次遇见便宜。</p><p>混合版本是一等故障模式。不写进规格的字段，滚动时会出现。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>滚动保持法定人数，制造长期混合版本。</li><li>编解码与 \\(\\delta\\) 要双向兼容或两阶段。</li><li>默认超时与 schema 都是协议；回滚要预先能反向。</li><li>出处：SRE 发布实践；Raft 成员；k8s 滚动更新。</li></ul>',10))])}const P=l(h,[["render",_]]);export{g as __pageData,P as default};
